// FR-002 データ永続化: 生成済み Prisma Client に better-sqlite3 adapter を渡して共有する
// 接続 URL は adapter 方式で渡す（schema.prisma の datasource には url を置かない）
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaClient } from "@/generated/prisma/client";

// 開発時のホットリロードで複数インスタンスが生成されるのを防ぐ
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

const adapter = new PrismaBetterSqlite3({
  url: process.env.DATABASE_URL ?? "file:./dev.db",
});

export const prisma = globalForPrisma.prisma ?? new PrismaClient({ adapter });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

// 共通ルール: エラー応答は { error: { code, message } } に統一する（spec/00_common.md）
import { NextResponse } from "next/server";

export type ErrorCode = "VALIDATION_ERROR" | "NOT_FOUND";

// バリデーション失敗などのドメインエラーを表す例外
export class AppError extends Error {
  readonly code: ErrorCode;
  readonly status: number;

  constructor(code: ErrorCode, message: string, status: number) {
    super(message);
    this.code = code;
    this.status = status;
  }
}

export class ValidationError extends AppError {
  constructor(message: string) {
    super("VALIDATION_ERROR", message, 400);
  }
}

export class NotFoundError extends AppError {
  constructor(message: string) {
    super("NOT_FOUND", message, 404);
  }
}

// 統一エラー形式の JSON レスポンスを返す
export function errorResponse(error: AppError) {
  return NextResponse.json(
    { error: { code: error.code, message: error.message } },
    { status: error.status },
  );
}

// 共有トリム検証（design/001_minimum_kanban.md バリデーション）
// Board・List は上限 100、Card は上限 200 と、上限だけを差し替えて使う
import { ValidationError } from "@/lib/errors";

// 前後の半角・全角空白、タブ、改行を除去する
// \s は全角空白(U+3000)を含まないため明示的に加える
const TRIM_PATTERN = /^[\s　]+|[\s　]+$/g;

export function trimTitle(raw: unknown): string {
  if (typeof raw !== "string") return "";
  return raw.replace(TRIM_PATTERN, "");
}

// トリム後に 1〜maxLength 文字であることを検証し、トリム後の値を返す
// 失敗時は ValidationError(400) を投げる
export function validateTitle(raw: unknown, maxLength: number): string {
  const trimmed = trimTitle(raw);
  if (trimmed.length < 1 || trimmed.length > maxLength) {
    throw new ValidationError(`タイトルは1〜${maxLength}文字で入力してください`);
  }
  return trimmed;
}

// FR-101 / FR-103 / FR-104 / FR-105 ボードのデータアクセス
import { prisma } from "@/lib/prisma";

// FR-101 / FR-104 一覧は createdAt の降順
export function listBoards() {
  return prisma.board.findMany({ orderBy: { createdAt: "desc" } });
}

// FR-103 / FR-105 ボード作成（title は検証済みのトリム後の値）
export function createBoard(title: string) {
  return prisma.board.create({ data: { title } });
}

export function findBoard(id: string) {
  return prisma.board.findUnique({ where: { id } });
}

// FR-003 ボード詳細画面の初期描画用に、ボード・リスト・カードをまとめて取得する
// リストは order 昇順、各リスト内のカードも order 昇順
export function getBoardDetail(id: string) {
  return prisma.board.findUnique({
    where: { id },
    include: {
      lists: {
        orderBy: { order: "asc" },
        include: { cards: { orderBy: { order: "asc" } } },
      },
    },
  });
}

// FR-201 / FR-203 / FR-204 / FR-205 リストのデータアクセス
import { prisma } from "@/lib/prisma";

// FR-201 / FR-204 同じボード内では order 昇順
export function listListsByBoard(boardId: string) {
  return prisma.list.findMany({
    where: { boardId },
    orderBy: { order: "asc" },
  });
}

export function findList(id: string) {
  return prisma.list.findUnique({ where: { id } });
}

// FR-203 リスト作成。order は同じボード内に0件なら0、以後は最大 order + 1
// 採番と作成を同一トランザクションで行い、(boardId, order) の重複を避ける
export function createList(boardId: string, title: string) {
  return prisma.$transaction(async (tx) => {
    const last = await tx.list.findFirst({
      where: { boardId },
      orderBy: { order: "desc" },
    });
    const order = last ? last.order + 1 : 0;
    return tx.list.create({ data: { boardId, title, order } });
  });
}

// FR-301 / FR-303 / FR-304 / FR-305 / FR-403 カードのデータアクセス
import { prisma } from "@/lib/prisma";

// FR-301 / FR-304 同じリスト内では order 昇順
export function listCardsByList(listId: string) {
  return prisma.card.findMany({
    where: { listId },
    orderBy: { order: "asc" },
  });
}

export function findCard(id: string) {
  return prisma.card.findUnique({ where: { id } });
}

// FR-303 カード作成。order は同じリスト内に0件なら0、以後は最大 order + 1
// 採番と作成を同一トランザクションで行い、(listId, order) の重複を避ける
export function createCard(listId: string, title: string) {
  return prisma.$transaction(async (tx) => {
    const last = await tx.card.findFirst({
      where: { listId },
      orderBy: { order: "desc" },
    });
    const order = last ? last.order + 1 : 0;
    return tx.card.create({ data: { listId, title, order } });
  });
}

// FR-403 カードタイトル更新（title は検証済みのトリム後の値、order は変更しない）
export function updateCardTitle(id: string, title: string) {
  return prisma.card.update({ where: { id }, data: { title } });
}

// FR-104 GET /api/boards, FR-105 POST /api/boards
import { NextRequest, NextResponse } from "next/server";
import { listBoards, createBoard } from "@/lib/repository/board";
import { validateTitle } from "@/lib/validation/title";
import { AppError, errorResponse } from "@/lib/errors";

const TITLE_MAX = 100;

// FR-104 全ボードを createdAt 降順で返す
export async function GET() {
  const boards = await listBoards();
  return NextResponse.json(boards);
}

// FR-105 トリム後のタイトルを検証してボードを作成する
export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}));
    const title = validateTitle(body?.title, TITLE_MAX);
    const board = await createBoard(title);
    return NextResponse.json(board, { status: 201 });
  } catch (e) {
    if (e instanceof AppError) return errorResponse(e);
    throw e;
  }
}

// FR-204 GET /api/boards/[id]/lists, FR-205 POST /api/boards/[id]/lists
import { NextRequest, NextResponse } from "next/server";
import { findBoard } from "@/lib/repository/board";
import { listListsByBoard, createList } from "@/lib/repository/list";
import { validateTitle } from "@/lib/validation/title";
import { AppError, NotFoundError, errorResponse } from "@/lib/errors";

const TITLE_MAX = 100;

type Params = { params: Promise<{ id: string }> };

// FR-204 対象ボードのリストを order 昇順で返す
export async function GET(_request: NextRequest, { params }: Params) {
  try {
    const { id } = await params;
    // 対象ボードが無ければ 404
    const board = await findBoard(id);
    if (!board) throw new NotFoundError("ボードが見つかりません");
    const lists = await listListsByBoard(id);
    return NextResponse.json(lists);
  } catch (e) {
    if (e instanceof AppError) return errorResponse(e);
    throw e;
  }
}

// FR-205 対象ボードの存在を先に確認し、存在すればトリム後のタイトルを検証して作成
export async function POST(request: NextRequest, { params }: Params) {
  try {
    const { id } = await params;
    // E-201 存在しないボードは、body が不正でも 404 を優先する
    const board = await findBoard(id);
    if (!board) throw new NotFoundError("ボードが見つかりません");
    const body = await request.json().catch(() => ({}));
    const title = validateTitle(body?.title, TITLE_MAX);
    const list = await createList(id, title);
    return NextResponse.json(list, { status: 201 });
  } catch (e) {
    if (e instanceof AppError) return errorResponse(e);
    throw e;
  }
}

// FR-304 GET /api/lists/[id]/cards, FR-305 POST /api/lists/[id]/cards
import { NextRequest, NextResponse } from "next/server";
import { findList } from "@/lib/repository/list";
import { listCardsByList, createCard } from "@/lib/repository/card";
import { validateTitle } from "@/lib/validation/title";
import { AppError, NotFoundError, errorResponse } from "@/lib/errors";

const TITLE_MAX = 200;

type Params = { params: Promise<{ id: string }> };

// FR-304 対象リストのカードを order 昇順で返す
export async function GET(_request: NextRequest, { params }: Params) {
  try {
    const { id } = await params;
    // 対象リストが無ければ 404
    const list = await findList(id);
    if (!list) throw new NotFoundError("リストが見つかりません");
    const cards = await listCardsByList(id);
    return NextResponse.json(cards);
  } catch (e) {
    if (e instanceof AppError) return errorResponse(e);
    throw e;
  }
}

// FR-305 対象リストの存在を先に確認し、存在すればトリム後のタイトルを検証して作成
export async function POST(request: NextRequest, { params }: Params) {
  try {
    const { id } = await params;
    // E-301 存在しないリストは、body が不正でも 404 を優先する
    const list = await findList(id);
    if (!list) throw new NotFoundError("リストが見つかりません");
    const body = await request.json().catch(() => ({}));
    const title = validateTitle(body?.title, TITLE_MAX);
    const card = await createCard(id, title);
    return NextResponse.json(card, { status: 201 });
  } catch (e) {
    if (e instanceof AppError) return errorResponse(e);
    throw e;
  }
}

// FR-403 PATCH /api/cards/[id]
import { NextRequest, NextResponse } from "next/server";
import { findCard, updateCardTitle } from "@/lib/repository/card";
import { validateTitle } from "@/lib/validation/title";
import { AppError, NotFoundError, errorResponse } from "@/lib/errors";

const TITLE_MAX = 200;

type Params = { params: Promise<{ id: string }> };

// FR-403 対象カードの存在を先に確認し、存在すればトリム後のタイトルを検証して更新
export async function PATCH(request: NextRequest, { params }: Params) {
  try {
    const { id } = await params;
    // E-401 存在しないカードは、body が不正でも 404 を優先する
    const card = await findCard(id);
    if (!card) throw new NotFoundError("カードが見つかりません");
    const body = await request.json().catch(() => ({}));
    const title = validateTitle(body?.title, TITLE_MAX);
    const updated = await updateCardTitle(id, title);
    return NextResponse.json(updated);
  } catch (e) {
    if (e instanceof AppError) return errorResponse(e);
    throw e;
  }
}

